function main(inputs) {
  var html = String(inputs.html == null ? "" : inputs.html);
  function normalize(s) {
    return String(s == null ? "" : s)
      .replace(/<[^>]*>/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }
  var titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  var title = titleMatch ? normalize(titleMatch[1]) : "";
  var mainMatch = html.match(/<main[^>]*>([\s\S]*?)<\/main>/i);
  var mainRaw = mainMatch ? normalize(mainMatch[1]) : "";
  var mainValue = mainRaw.length > 0 ? mainRaw : "空";
  return { title: title, main: mainValue, joined: title + "|" + mainValue };
}
